import React,{useState} from 'react';
export default function Experiments({state='ready'}){const [metric,setMetric]=useState('Completion');if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
return <div className="shell"><span className="eyebrow">Experiment workspace</span><h1>Compare the outcome, not just the headline.</h1><p>Reference results show how a purpose-built comparison could work.</p><div className="row"><button className="btn ghost" onClick={()=>setMetric('Completion')}>Completion</button><button id="quality" className="btn" onClick={()=>setMetric('Quality')}>Task quality</button></div><section className="panel spacer"><h2 id="result">{metric} comparison</h2><table><thead><tr><th>Variant</th><th>Reference score</th><th>Tradeoff</th></tr></thead><tbody><tr><td>Guided flow</td><td>{metric==='Completion'?'81%':'94 / 100'}</td><td>More structure, fewer mistakes</td></tr><tr><td>Compact workbench</td><td>{metric==='Completion'?'88%':'86 / 100'}</td><td>Faster for experienced operators</td></tr></tbody></table><p className="muted spacer">These are synthetic reference values, not a measured product experiment.</p></section></div>;}
